<?php

namespace App\Models;

use App\Models\Abstracts\BaseModel;
use App\Models\Concerns\LogsModelActivity;
use Database\Factories\PurchaseOrderReceiptFactory;
use Illuminate\Database\Eloquent\Attributes\Fillable;
use Illuminate\Database\Eloquent\Factories\HasFactory;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Database\Eloquent\Relations\HasMany;

/**
 * Delivery of a purchase order (spec 0254, D-1). `created_by` and `purchase_invoice_id`
 * (receipt generated by an invoice, D-12) are written by the service, never by the client.
 */
#[Fillable(['receipt_date', 'delivery_note_number', 'delivery_note_date', 'notes'])]
class PurchaseOrderReceipt extends BaseModel
{
    /** @use HasFactory<PurchaseOrderReceiptFactory> */
    use HasFactory, LogsModelActivity;

    /**
     * @return array<string, mixed>
     */
    protected function casts(): array
    {
        return [
            'receipt_date' => 'date',
            'delivery_note_date' => 'date',
        ];
    }

    /**
     * @return BelongsTo<PurchaseOrder, $this>
     */
    public function purchaseOrder(): BelongsTo
    {
        return $this->belongsTo(PurchaseOrder::class);
    }

    /**
     * @return HasMany<PurchaseOrderReceiptLine, $this>
     */
    public function lines(): HasMany
    {
        return $this->hasMany(PurchaseOrderReceiptLine::class)->orderBy('id');
    }

    /**
     * @return BelongsTo<PurchaseInvoice, $this>
     */
    public function purchaseInvoice(): BelongsTo
    {
        return $this->belongsTo(PurchaseInvoice::class);
    }

    /**
     * @return BelongsTo<User, $this>
     */
    public function createdBy(): BelongsTo
    {
        return $this->belongsTo(User::class, 'created_by');
    }
}
